-- 1. GET /Transactions: one page of a branch
DECLARE @branch varchar(5) = 'BR001';
DECLARE @p int = 0;
DECLARE @p2 int = 20;

SELECT [c].[Id], [c].[BranchCode] AS [Branch], [c].[OpenedAt], [c].[Status], [p].[TransactionId], [p].[CreatedAtUtc], [p].[CreatedBy], [p].[Method], [p].[ModifiedAtUtc], [p].[PaidAt], [p].[Tax]
FROM [CounterTransactions] AS [c]
LEFT JOIN [Payments] AS [p] ON [c].[Id] = [p].[TransactionId]
WHERE [c].[BranchCode] = @branch
ORDER BY [c].[OpenedAt] DESC, [c].[Id] DESC
OFFSET @p ROWS FETCH NEXT @p2 ROWS ONLY

-- 2. GET /Reports/ShippingVolume: groups of one branch
DECLARE @start datetime2 = '2026-10-18T00:00:00.0000000Z';
DECLARE @end datetime2 = '2026-11-02T00:00:00.0000000Z';
DECLARE @branch varchar(5) = 'BR001';

SELECT [s].[ZoneCode], [s].[Level], [s].[WeightGrams] AS [Weight], [s].[LengthCm], [s].[WidthCm], [s].[HeightCm], COUNT(*) AS [Count], COALESCE(SUM(CAST([s].[Price] AS decimal(18,2))), 0.0) AS [Revenue]
FROM [Shipments] AS [s]
INNER JOIN (
    SELECT [c].[Id]
    FROM [CounterTransactions] AS [c]
    LEFT JOIN [Payments] AS [p] ON [c].[Id] = [p].[TransactionId]
    WHERE [c].[Status] = 'Paid' AND [p].[PaidAt] >= @start AND [p].[PaidAt] < @end AND [c].[BranchCode] = @branch
) AS [s0] ON [s].[TransactionId] = [s0].[Id]
GROUP BY [s].[ZoneCode], [s].[Level], [s].[WeightGrams], [s].[LengthCm], [s].[WidthCm], [s].[HeightCm]

-- 3. GET /Reports/MoneyOrders: rows of the period
DECLARE @branch varchar(5) = 'BR001';
DECLARE @start datetime2 = '2026-10-18T00:00:00.0000000Z';
DECLARE @end datetime2 = '2026-11-02T00:00:00.0000000Z';
DECLARE @start0 datetime2 = '2026-10-18T00:00:00.0000000Z';
